    (v_route, 'Bazilika na Svaté Hoře', 'Bazilika v obci Głogówko. Památka v Polsku — kus historie přímo u trasy.', 51.8856, 17.0356, 'http://commons.wikimedia.org/wiki/Special:FilePath/Klasztor%20Gostyn.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Klasztor%20Gostyn.jpg"}'::text[], 0, '{"en": {"name": "Basilica on the Holy Mountain", "description": "Church building in Głogówko, Greater Poland Voivodeship, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Mariä-Empfängnis-Basilika (Głogówko)", "description": "Kloster in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika na Świętej Górze", "description": "Zespół klasztorny w Głogówku w województwie wielkopolskim. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Bazilika na Svaté Hoře", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Bazilika na Svaté Hoře", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique de Sainte-Colline", "description": "Basilique mineure en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bazilika na Svaté Hoře", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
