    (v_route, 'Klášter Gaming', 'Původně kartuziánský klášter, založený r. 1330 rakouským vévodou Albrechtem II. (1298-1358) v Gamingu (Rakousko). Klášter byl zrušen r. 1782. Dnes je v části klášterních budov hotel a zbytek je věnován vzdělávacím institucím. Památka v Rakousku — kus historie přímo u trasy.', 47.9233, 15.0817, 'http://commons.wikimedia.org/wiki/Special:FilePath/Gaming%20-%20Kartause%20%282%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Gaming%20-%20Kartause%20%282%29.JPG"}'::text[], 1, '{"en": {"name": "Gaming Charterhouse", "description": "Former Carthusian monastery in Gaming, Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Kartause Mariathron, Gaming", "description": "Ehemaliges Kartäuserkloster „Marienthron“ in Gaming, Niederösterreich. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klášter Gaming", "description": "Muzeum w Austrii. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Klášter Gaming", "description": "Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Cartuja de Gaming", "description": "Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "chartreuse de Gaming", "description": "Musée en Autriche. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Gaming", "description": "Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
