    (v_route, 'New Synagogue', 'Památka v Polsku — kus historie přímo u trasy.', 51.10454, 17.02834, 'http://commons.wikimedia.org/wiki/Special:FilePath/Neue%20Synagoge%20in%20Breslau.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Neue%20Synagoge%20in%20Breslau.jpg"}'::text[], 0, '{"en": {"name": "New Synagogue", "description": "The New Synagogue was the largest synagogue in Breslau, Germany. It was one of the largest synagogues in the German Empire and a centre of Reform Judaism in Breslau. It was built in 1865–1872, and designed by Edwin Oppler. It was burnt down during th. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Neue Synagoge", "description": "Synagoge in Breslau. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Nowa Synagoga we Wrocławiu", "description": "Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Nieuwe Synagoge van Breslau", "description": "Gebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "New Synagogue", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "New Synagogue", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Нова синагога (Бреслау)", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
